with unpacked as (select id, effective_from, currency, tier_prices, discounts, zip_with(tier_prices, discounts, (p, d) -> round(p * (1 - d), 2)) as net_prices, aggregate(tier_prices, 0D, (acc, p) -> acc + p, acc -> round(acc / size(tier_prices), 2)) as avg_tier_price, transform(tier_prices, (p, i) -> round(p * tier_limits[i], 2)) as tier_revenue_caps, slice(tier_limits, 1, 2) as first_two_limits, element_at(tier_prices, 1) as entry_price from price_tiers) select id, effective_from, currency, entry_price, min(avg_tier_price) over (partition by currency order by entry_price asc, id asc rows between 2 preceding and current row) last3_min_avg_tier_price, sum(avg_tier_price) over (partition by currency order by entry_price asc, id asc rows between 2 preceding and current row) last3_sum_avg_tier_price, max(avg_tier_price) over (partition by currency order by entry_price asc, id asc rows between 2 preceding and current row) last3_max_avg_tier_price, count(avg_tier_price) over (partition by currency order by entry_price asc, id asc rows between 2 preceding and current row) last3_count_avg_tier_price, row_number() over (partition by currency order by avg_tier_price asc, id asc) event_seq from unpacked
